namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<(string Reference, decimal Net)>();
        var seen = new HashSet<string>(StringComparer.Ordinal);
        var acceptedTotal = 0m;

        foreach (var item in items)
        {
            var rejection = GetRejectionReason(item, settlementCurrency, seen);
            if (rejection is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejection));
                continue;
            }

            var net = CalculateNet(item.GrossAmount, percentageFee, fixedFee);
            rejection = GetFinancialRejectionReason(net, acceptedTotal, submissionLimit);
            if (rejection is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejection));
                continue;
            }

            accepted.Add((item.Reference, net));
            acceptedTotal += net;
        }

        return CompleteSettlement(
            merchantId, settlementCurrency, gateway, lines, accepted, acceptedTotal);
    }

    private static string? GetRejectionReason(
        PaymentItem item, string settlementCurrency, HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return "invalid-reference";
        if (!seen.Add(item.Reference))
            return "duplicate";
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
            return "currency-mismatch";
        if (item.GrossAmount <= 0m)
            return "invalid-amount";
        if (item.Refunded)
            return "refunded";
        if (item.Held)
            return "held";

        return null;
    }

    private static decimal CalculateNet(decimal grossAmount, decimal percentageFee, decimal fixedFee)
    {
        var fee = decimal.Round(grossAmount * percentageFee + fixedFee, 2);
        return decimal.Round(grossAmount - fee, 2);
    }

    private static string? GetFinancialRejectionReason(
        decimal net, decimal acceptedTotal, decimal submissionLimit)
    {
        if (net <= 0m)
            return "fee-exceeds-amount";
        if (acceptedTotal + net > submissionLimit)
            return "batch-limit";

        return null;
    }

    private static SettlementResult CompleteSettlement(
        string merchantId,
        string settlementCurrency,
        ISettlementGateway gateway,
        List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted,
        decimal total)
    {
        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");
        if (string.IsNullOrWhiteSpace(merchantId))
            return RejectedResult(lines, accepted, "invalid-merchant");

        var references = accepted.Select(entry => entry.Reference).ToArray();
        var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total, references);
        if (!gatewayResult.Accepted)
            return RejectedResult(lines, accepted, $"gateway-{gatewayResult.Code}");

        lines.AddRange(accepted.Select(entry =>
            new SettlementLine(entry.Reference, entry.Net, "submitted")));
        var status = lines.Any(line => line.Status != "submitted") ? "partial" : "submitted";
        return new SettlementResult(lines, total, status);
    }

    private static SettlementResult RejectedResult(
        List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted,
        string status)
    {
        var rejectedLines = accepted.Select(entry =>
            new SettlementLine(entry.Reference, 0m, status));
        return new SettlementResult([.. lines, .. rejectedLines], 0m, "rejected");
    }
}
